import sys
def _fail(t, e, tb, _d=sys.excepthook):
    if issubclass(t, AssertionError):
        print('check failed:', e); sys.exit(1)
    _d(t, e, tb)
sys.excepthook = _fail
import subprocess
want = {'public/agents/doc-change-detection.md': 157, 'public/agents/doc-lookup-sources.md': 88, 'public/arch/fluent-rust-typescript.md': 52, 'public/privacy/nist-sp800-38g.md': 9}
o = subprocess.run([sys.executable, '_tools/rag.py', 'audit', '--root', 'public'], capture_output=True, text=True, timeout=600).stdout
have = {}
